#:sdk Microsoft.NET.Sdk.Web
#:property PublishAot=false

// (That second line just silences native-AOT trimming warnings that
// file-based web apps emit for reflection-based JSON — ignore it.)
//
// 20 — error handling (ORIGINAL, flawed on purpose)
//
// An inventory API where every endpoint wraps its whole body in try/catch and
// invents its OWN error format. Three different error shapes, one swallowed
// exception, and a domain layer that throws generic Exception for everything.
//
// Run:   dotnet run csharp/20-error-handling-problemdetails/original.cs
// Try:
//   curl -i http://localhost:5020/items
//   curl -i http://localhost:5020/items/99
//        -> 500 {"err":"no item with id 99"}                    (shape #1 — and why 500?!)
//   curl -i -X POST http://localhost:5020/items/3/purchase
//        -> run twice; second time: 400 {"message":"...","ok":false}  (shape #2)
//   curl -i -X POST "http://localhost:5020/items?name=&category=paper&stock=-1"
//        -> 500 plain text "ERROR: name is required"            (shape #3)
//   curl -i "http://localhost:5020/items/by-category/electronixs"
//        -> 200 []   <-- typo'd category, yet it LOOKS like success. THE BUG.

var app = WebApplication.CreateBuilder(args).Build();

var items = new List<Item>
{
    new() { Id = 1, Name = "Keyboard", Category = "electronics", Stock = 12 },
    new() { Id = 2, Name = "Notebook", Category = "paper",       Stock = 40 },
    new() { Id = 3, Name = "Webcam",   Category = "electronics", Stock = 1  },
};

app.MapGet("/items", () => items);

app.MapGet("/items/{id}", (int id) =>
{
    try
    {
        return Results.Ok(Inventory.Find(items, id));
    }
    catch (Exception ex)
    {
        // Error shape #1: {"err": "..."} — and a 500, even though "not found"
        // is the CLIENT asking for something that isn't there (should be 404).
        return Results.Json(new { err = ex.Message }, statusCode: 500);
    }
});

app.MapGet("/items/by-category/{category}", (string category) =>
{
    try
    {
        return Results.Ok(Inventory.ByCategory(items, category));
    }
    catch
    {
        // "An exception here probably just means nothing matched." (It does NOT.)
        // ByCategory only throws for a category that doesn't exist AT ALL — a
        // typo like /items/by-category/electronixs lands here, and the caller
        // gets 200 OK with []. That's indistinguishable from a real, empty
        // category. The frontend renders "no items yet" and NOBODY ever finds
        // out the request was wrong. This is THE BUG of this project:
        // a swallowed exception dressed up as success.
        return Results.Ok(new List<Item>());
    }
});

app.MapPost("/items", (string? name, string? category, int stock) =>
{
    try
    {
        return Results.Ok(Inventory.Add(items, name, category, stock));
    }
    catch (Exception ex)
    {
        // Error shape #3: raw text, no JSON at all — and 500 for what is
        // really the user's input problem (should be 400).
        return Results.Text("ERROR: " + ex.Message, "text/plain", statusCode: 500);
    }
});

app.MapPost("/items/{id}/purchase", (int id) =>
{
    try
    {
        return Results.Ok(Inventory.Purchase(items, id));
    }
    catch (Exception ex)
    {
        // Error shape #2: {"message": "...", "ok": false} — different keys,
        // different status. And because the domain throws plain Exception for
        // EVERYTHING, "no item with id 99" (a 404 story) and "out of stock"
        // (a 409 story) both come out as 400 here. The catch block cannot
        // tell them apart — the exception type carries no information.
        return Results.BadRequest(new { message = ex.Message, ok = false });
    }
});

app.Run("http://localhost:5020");

class Item
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Category { get; set; } = "";
    public int Stock { get; set; }
}

static class Inventory
{
    public static readonly string[] KnownCategories = { "electronics", "paper", "furniture" };

    // Generic Exception for every failure — the caller can't tell "not found"
    // from "out of stock" from "bad input" without parsing message strings.
    public static Item Find(List<Item> items, int id)
        => items.FirstOrDefault(i => i.Id == id)
           ?? throw new Exception($"no item with id {id}");

    public static List<Item> ByCategory(List<Item> items, string category)
    {
        if (!KnownCategories.Contains(category))
            throw new Exception($"unknown category '{category}'");
        return items.Where(i => i.Category == category).ToList();
    }

    public static Item Purchase(List<Item> items, int id)
    {
        var item = Find(items, id);
        if (item.Stock <= 0)
            throw new Exception($"'{item.Name}' is out of stock");
        item.Stock--;
        return item;
    }

    public static Item Add(List<Item> items, string? name, string? category, int stock)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new Exception("name is required");
        if (category is null || !KnownCategories.Contains(category))
            throw new Exception($"unknown category '{category}'");
        if (stock < 0)
            throw new Exception("stock cannot be negative");
        var item = new Item
        {
            Id = items.Max(i => i.Id) + 1,
            Name = name.Trim(),
            Category = category,
            Stock = stock,
        };
        items.Add(item);
        return item;
    }
}

# 🏋️ Practice: Error Handling & ProblemDetails

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Restock an item (warm-up)

Add `InventoryService.Restock(int id, int amount)` (raises stock by `amount`) and
`POST /items/{id}/restock` taking `{"amount":5}`. Unknown id → 404, `amount <= 0` → 400 — and here's
the point: you get both **without writing a single catch or status code**, because the exceptions you
throw are already in the mapper's table.
*Practices:* the domain layer + feeling the one-middleware design pay for itself.
**Hint:** throw `ItemNotFoundException` and `ArgumentException`; copy `Purchase`'s lock-and-`with` shape.
**Check offline:** `Check.Equal(15, inv.Restock(1, 3).Stock, "restock adds")` and
`Check.Throws<ArgumentException>(() => inv.Restock(1, 0), "zero is not a restock")` pass;
`curl -i -X POST http://localhost:5020/items/99/restock -H "Content-Type: application/json" -d "{\"amount\":5}"` → `404` ProblemDetails.

### ⭐⭐ 2. Duplicate names are a conflict (core)

Adding an item whose name already exists (case-insensitive, trimmed) should fail with
`409 Conflict`. Create `DuplicateItemNameException`, throw it from `Add`, and give it a row in
`ErrorMapper` with title `"Duplicate item"`.
*Practices:* the full new-error-type route: domain exception → mapper row → tests, zero endpoint edits.
**Hint:** the check goes inside `Add`'s lock, after the name/stock/category validation.
**Check offline:** add this Check test — it should pass:
`Check.Throws<DuplicateItemNameException>(() => inv.Add("  keyboard ", "electronics", 1), "names collide case-insensitively");`
plus `Check.Equal(409, ErrorMapper.Map(new DuplicateItemNameException("Pen")).Status, "duplicates map to 409");`

### ⭐⭐ 3. Machine-readable error codes (core)

`title` is for humans; frontends prefer a stable code to switch on. Extend `Map` to return a fourth
tuple element `Code` (`"item_not_found"`, `"unknown_category"`, `"out_of_stock"`, `"invalid_input"`,
`"duplicate_item"`, `"server_error"`) and have the middleware put it into the ProblemDetails body via
the `extensions` parameter of `Results.Problem`.
*Practices:* evolving the policy table + ProblemDetails extension members.
**Hint:** named tuple elements mean old code reading `.Status`/`.Detail` keeps compiling; extensions is
`new Dictionary<string, object?> { ["code"] = code }`.
**Check offline:** `Check.Equal("item_not_found", ErrorMapper.Map(new ItemNotFoundException(1)).Code, "stable code")` passes; `curl -s http://localhost:5020/items/99` → body now contains `"code":"item_not_found"`.

### ⭐⭐ 4. DELETE /items/{id} (core)

Add `InventoryService.Remove(int id)` (throws `ItemNotFoundException` when absent) and
`DELETE /items/{id}` answering `204 No Content`. Deleting twice: first 204, then a ProblemDetails 404
— same envelope as every other failure in the app.
*Practices:* reusing an existing domain exception instead of inventing a second "not found" path.
**Hint:** `void` is an honest return here — "it worked or it threw"; the endpoint returns `Results.NoContent()`.
**Check offline:** `Check.Throws<ItemNotFoundException>(() => { inv.Remove(3); inv.Remove(3); }, "second delete throws")` passes; `curl -i -X DELETE http://localhost:5020/items/2` twice → `204` then `404`.

### ⭐⭐⭐ 5. All-or-nothing batch purchase (challenge)

Add `POST /items/purchase-batch` taking `{"ids":[1,2,1]}`: purchase every listed id (duplicates mean
multiple units!) or **none of them**. If id 3 has 1 in stock, `{"ids":[2,3,3]}` must throw
`OutOfStockException` and leave item 2's stock *untouched* — no half-finished orders. Write the test
proving nothing changed before you trust it.
*Practices:* transactional thinking in the pure domain layer: validate everything, then mutate.
**Hint:** inside one `lock`, first loop over `ids.GroupBy(id => id)` checking `item.Stock >= group.Count()`, and only after every check passes, do the decrements.
**Check offline:** add these Check tests — they should pass:
`Check.Throws<OutOfStockException>(() => inv.PurchaseMany(new[] { 2, 3, 3 }), "one bad id sinks the batch");`
`Check.Equal(40, inv.Get(2).Stock, "and the good id was NOT decremented");`

## Solutions

### 1. Restock

```csharp
// InventoryService.cs
public Item Restock(int id, int amount)
{
    if (amount <= 0) throw new ArgumentException("restock amount must be positive");
    lock (_lock)
    {
        var item = _items.FirstOrDefault(i => i.Id == id) ?? throw new ItemNotFoundException(id);
        var updated = item with { Stock = item.Stock + amount };
        _items[_items.IndexOf(item)] = updated;
        return updated;
    }
}

// Program.cs — no try/catch, like every other endpoint
app.MapPost("/items/{id}/restock", (int id, RestockDto dto, InventoryService inv)
    => Results.Ok(inv.Restock(id, dto.Amount)));

// bottom of Program.cs, next to NewItem
public record RestockDto(int Amount);
```

WHY: both failure paths ride rails that already exist — `ItemNotFoundException` → 404 and
`ArgumentException` → 400 are rows in the mapper's table. That's the compounding payoff of the
design: each new feature buys its error handling for free, instead of pasting a fresh try/catch.

### 2. Duplicate names

```csharp
// DomainExceptions.cs
public class DuplicateItemNameException : Exception
{
    public DuplicateItemNameException(string name)
        : base($"an item named '{name}' already exists") { }
}

// InventoryService.cs — inside Add, first line within the lock
if (_items.Any(i => string.Equals(i.Name, name.Trim(), StringComparison.OrdinalIgnoreCase)))
    throw new DuplicateItemNameException(name.Trim());

// ErrorMapper.cs — one new row, above the catch-all
DuplicateItemNameException e => (409, "Duplicate item", e.Message),

// Tests.cs
Check.Throws<DuplicateItemNameException>(() => inv.Add("  keyboard ", "electronics", 1),
    "names collide case-insensitively");
Check.Equal(409, ErrorMapper.Map(new DuplicateItemNameException("Pen")).Status, "duplicates map to 409");
Check.Equal(3, inv.GetAll().Count, "the rejected duplicate was never stored");
```

WHY: 409 because the *request* is fine — it's the current state of the inventory that says no, the
same reasoning as out-of-stock. The check sits inside the lock so two simultaneous adds can't both
pass it; the endpoint layer never learns this rule exists, which is how it should be.

### 3. Error codes

```csharp
// ErrorMapper.cs — the tuple grows a named element
public static (int Status, string Title, string Detail, string Code) Map(Exception ex) => ex switch
{
    ItemNotFoundException e      => (404, "Item not found", e.Message, "item_not_found"),
    UnknownCategoryException e   => (400, "Unknown category", e.Message, "unknown_category"),
    OutOfStockException e        => (409, "Out of stock", e.Message, "out_of_stock"),
    DuplicateItemNameException e => (409, "Duplicate item", e.Message, "duplicate_item"),
    ArgumentException e          => (400, "Invalid input", e.Message, "invalid_input"),
    _                            => (500, "Unexpected server error",
                                     "Something went wrong on our side. The details were logged.", "server_error"),
};

// Program.cs — the middleware forwards it
var (status, title, detail, code) = ErrorMapper.Map(ex);
if (status == 500) app.Logger.LogError(ex, "Unhandled exception");
await Results.Problem(title: title, detail: detail, statusCode: status,
        extensions: new Dictionary<string, object?> { ["code"] = code })
    .ExecuteAsync(context);

// Tests.cs
Check.Equal("item_not_found", ErrorMapper.Map(new ItemNotFoundException(1)).Code, "stable code for 404s");
Check.Equal("server_error", ErrorMapper.Map(new Exception("x")).Code, "bugs get the generic code");
```

WHY: `detail` strings are for reading, not `if`-ing — the moment a frontend writes
`if (problem.detail.includes("out of stock"))` you can never reword a message again. A `code` is a
contract you keep stable while prose stays free. RFC 9457 explicitly allows extension members, and
`Results.Problem` serializes them as top-level JSON fields; existing tests keep passing because the
old tuple element *names* still exist.

### 4. Delete

```csharp
// InventoryService.cs
public void Remove(int id)
{
    lock (_lock)
    {
        var item = _items.FirstOrDefault(i => i.Id == id) ?? throw new ItemNotFoundException(id);
        _items.Remove(item);
    }
}

// Program.cs
app.MapDelete("/items/{id}", (int id, InventoryService inv) =>
{
    inv.Remove(id);
    return Results.NoContent();
});
```

WHY: `Remove` returning `void` looks odd after cs#16's `bool Remove` — but this app's convention is
"failure throws", and mixing conventions is worse than either alone. The second DELETE's 404 comes
out dressed exactly like `GET /items/99`'s, because both are the same exception taking the same road
through the same middleware.

### 5. Batch purchase

```csharp
// InventoryService.cs
/// All-or-nothing: either every id is purchasable (duplicates = multiple
/// units) and all stocks drop, or nothing changes and the problem is thrown.
public IReadOnlyList<Item> PurchaseMany(IEnumerable<int> ids)
{
    lock (_lock)
    {
        var wanted = ids.ToList();
        foreach (var group in wanted.GroupBy(id => id))          // validate FIRST...
        {
            var item = _items.FirstOrDefault(i => i.Id == group.Key)
                ?? throw new ItemNotFoundException(group.Key);
            if (item.Stock < group.Count())
                throw new OutOfStockException(item.Name);
        }
        var result = new List<Item>();
        foreach (var id in wanted)                                // ...mutate ONLY after
        {
            var item = _items.First(i => i.Id == id);
            var updated = item with { Stock = item.Stock - 1 };
            _items[_items.IndexOf(item)] = updated;
            result.Add(updated);
        }
        return result;
    }
}

// Program.cs
app.MapPost("/items/purchase-batch", (PurchaseBatch dto, InventoryService inv)
    => Results.Ok(inv.PurchaseMany(dto.Ids ?? new List<int>())));
public record PurchaseBatch(List<int>? Ids);

// Tests.cs
var inv = NewService();
Check.Equal(3, inv.PurchaseMany(new[] { 1, 2, 1 }).Count, "a batch returns every purchase");
Check.Equal(10, inv.Get(1).Stock, "duplicated ids decrement twice");
Check.Throws<OutOfStockException>(() => inv.PurchaseMany(new[] { 2, 3, 3 }), "one bad id sinks the batch");
Check.Equal(39, inv.Get(2).Stock, "and the good id was NOT decremented");
Check.Throws<ItemNotFoundException>(() => inv.PurchaseMany(new[] { 1, 99 }), "missing ids sink it too");
```

WHY: the naive loop-and-purchase would throw halfway and leave item 2 already decremented — a
half-shipped order no one can see in any response. Validate-then-mutate inside one lock is the
in-memory version of a database transaction: the throw happens while the state is still pristine.
`GroupBy` is what catches the sneaky `[3,3]`-against-stock-1 case that a simple per-id existence
check would wave through.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// Domain exceptions: one class per EXPECTED failure. The type itself carries
// the meaning ("this item doesn't exist"), so the HTTP layer can map type ->
// status code without ever parsing message strings. Compare project 08, where
// a Result type played this role for a console app — exceptions + one mapping
// middleware is the idiomatic ASP.NET Core version of the same separation.

public class ItemNotFoundException : Exception
{
    public ItemNotFoundException(int id) : base($"no item with id {id}") { }
}

public class OutOfStockException : Exception
{
    public OutOfStockException(string itemName) : base($"'{itemName}' is out of stock") { }
}

public class UnknownCategoryException : Exception
{
    public UnknownCategoryException(string category)
        : base($"unknown category '{category}' (known: {string.Join(", ", InventoryService.KnownCategories)})") { }
}

// ONE table that decides, for the entire app, which exception becomes which
// HTTP status. Pure function: exception in, (status, title, detail) out —
// which is exactly what makes it testable without HTTP (see Tests.cs).
//
// Note the last arm: an exception we did NOT expect is a bug, so the client
// gets a generic 500 and the real message stays on the server. Leaking raw
// internals ("NullReferenceException at Db.cs line 214") to strangers is a
// security hole, not transparency.

public static class ErrorMapper
{
    public static (int Status, string Title, string Detail) Map(Exception ex) => ex switch
    {
        ItemNotFoundException e    => (404, "Item not found", e.Message),
        UnknownCategoryException e => (400, "Unknown category", e.Message),
        OutOfStockException e      => (409, "Out of stock", e.Message),
        ArgumentException e        => (400, "Invalid input", e.Message),
        _                          => (500, "Unexpected server error",
                                       "Something went wrong on our side. The details were logged."),
    };
}

// The domain layer: all inventory DECISIONS live here, with zero knowledge of
// HTTP. Expected failures are thrown as specific domain exceptions; the
// middleware in Program.cs translates them. That's why every method here is
// testable without starting a server (see Tests.cs).

public record Item(int Id, string Name, string Category, int Stock);

public class InventoryService
{
    public static readonly string[] KnownCategories = { "electronics", "paper", "furniture" };

    private readonly List<Item> _items;
    private readonly object _lock = new();

    public InventoryService() : this(DefaultItems()) { }

    // Tests inject their own seed data through this constructor.
    public InventoryService(IEnumerable<Item> seed) => _items = seed.ToList();

    private static List<Item> DefaultItems() => new()
    {
        new(1, "Keyboard", "electronics", 12),
        new(2, "Notebook", "paper",       40),
        new(3, "Webcam",   "electronics",  1),
    };

    public IReadOnlyList<Item> GetAll()
    {
        lock (_lock) return _items.ToList();
    }

    public Item Get(int id)
    {
        lock (_lock)
            return _items.FirstOrDefault(i => i.Id == id)
                ?? throw new ItemNotFoundException(id);
    }

    public IReadOnlyList<Item> ByCategory(string category)
    {
        if (!KnownCategories.Contains(category))
            throw new UnknownCategoryException(category);   // a typo is an ERROR, not an empty list
        lock (_lock)
            return _items.Where(i => i.Category == category).ToList();
    }

    public Item Purchase(int id)
    {
        lock (_lock)
        {
            var item = _items.FirstOrDefault(i => i.Id == id)
                ?? throw new ItemNotFoundException(id);
            if (item.Stock <= 0)
                throw new OutOfStockException(item.Name);
            var updated = item with { Stock = item.Stock - 1 };
            _items[_items.IndexOf(item)] = updated;
            return updated;
        }
    }

    public Item Add(string? name, string? category, int stock)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new ArgumentException("name is required");
        if (stock < 0)
            throw new ArgumentException("stock cannot be negative");
        if (category is null || !KnownCategories.Contains(category))
            throw new UnknownCategoryException(category ?? "(none)");
        lock (_lock)
        {
            var id = _items.Count == 0 ? 1 : _items.Max(i => i.Id) + 1;
            var item = new Item(id, name.Trim(), category, stock);
            _items.Add(item);
            return item;
        }
    }
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);
// Register a ready-made instance (not AddSingleton<InventoryService>()): the
// service also has a test-only IEnumerable<Item> constructor, and the DI
// container would prefer it — injecting an EMPTY sequence. Constructing the
// instance ourselves keeps the seeded default.
builder.Services.AddSingleton(new InventoryService());
var app = builder.Build();

// THE error handler — the only try/catch in the whole web app. Every endpoint
// below just does its job and throws when it can't; this middleware turns the
// exception into a ProblemDetails response (the web's standard error envelope:
// application/problem+json with type/title/status/detail fields, RFC 9457).
app.Use(async (context, next) =>
{
    try
    {
        await next(context);
    }
    catch (Exception ex)
    {
        var (status, title, detail) = ErrorMapper.Map(ex);
        if (status == 500)
            app.Logger.LogError(ex, "Unhandled exception");   // real message goes to the log...
        await Results.Problem(title: title, detail: detail, statusCode: status)
            .ExecuteAsync(context);                            // ...generic one goes to the client
    }
});

// Look: not one try/catch below. Endpoints translate HTTP <-> domain, period.
app.MapGet("/items", (InventoryService inv) => Results.Ok(inv.GetAll()));

app.MapGet("/items/{id}", (int id, InventoryService inv) => Results.Ok(inv.Get(id)));

app.MapGet("/items/by-category/{category}", (string category, InventoryService inv)
    => Results.Ok(inv.ByCategory(category)));

app.MapPost("/items", (NewItem dto, InventoryService inv) =>
{
    var item = inv.Add(dto.Name, dto.Category, dto.Stock);
    return Results.Created($"/items/{item.Id}", item);
});

app.MapPost("/items/{id}/purchase", (int id, InventoryService inv) => Results.Ok(inv.Purchase(id)));

// A deliberately unexpected crash, so you can see what a real bug looks like
// to a client: a generic 500 ProblemDetails that leaks nothing.
app.MapGet("/boom", string () => throw new InvalidOperationException(
    "simulated bug: this message must NOT reach the client"));

app.Run("http://localhost:5020");

public record NewItem(string? Name, string? Category, int Stock);

public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("ErrorMapper: exception type -> HTTP status (the whole point of this project)");
        Check.Equal(404, ErrorMapper.Map(new ItemNotFoundException(7)).Status, "ItemNotFoundException -> 404");
        Check.Equal(400, ErrorMapper.Map(new UnknownCategoryException("typo")).Status, "UnknownCategoryException -> 400");
        Check.Equal(409, ErrorMapper.Map(new OutOfStockException("Webcam")).Status, "OutOfStockException -> 409");
        Check.Equal(400, ErrorMapper.Map(new ArgumentException("bad")).Status, "ArgumentException -> 400");
        Check.Equal(500, ErrorMapper.Map(new InvalidOperationException("bug")).Status, "anything unexpected -> 500");

        Console.WriteLine("ErrorMapper: expected failures explain themselves, bugs stay private");
        Check.Equal("no item with id 7", ErrorMapper.Map(new ItemNotFoundException(7)).Detail,
            "expected failure keeps its message as the detail");
        var secretBug = new InvalidOperationException("password=hunter2 leaked in stack trace");
        Check.True(!ErrorMapper.Map(secretBug).Detail.Contains("hunter2"),
            "unexpected failure does NOT leak the internal message");
        Check.Equal("Unexpected server error", ErrorMapper.Map(secretBug).Title,
            "unexpected failure gets a generic title");

        Console.WriteLine("InventoryService: lookups");
        var inv = NewService();
        Check.Equal(3, inv.GetAll().Count, "seed data has 3 items");
        Check.Equal("Webcam", inv.Get(3).Name, "Get finds an existing item");
        Check.Throws<ItemNotFoundException>(() => inv.Get(99), "Get on a missing id throws ItemNotFoundException");

        Console.WriteLine("InventoryService: by-category (the swallowed-exception bug, fixed)");
        Check.Equal(2, inv.ByCategory("electronics").Count, "known category returns its items");
        Check.Equal(0, inv.ByCategory("furniture").Count, "known-but-empty category returns [] (a REAL empty list)");
        Check.Throws<UnknownCategoryException>(() => inv.ByCategory("electronixs"),
            "typo'd category THROWS instead of faking an empty success");

        Console.WriteLine("InventoryService: purchase");
        inv = NewService();
        Check.Equal(11, inv.Purchase(1).Stock, "purchase decrements stock");
        Check.Equal(0, inv.Purchase(3).Stock, "last unit can be purchased");
        Check.Throws<OutOfStockException>(() => inv.Purchase(3), "purchasing at 0 stock throws OutOfStockException");
        Check.Throws<ItemNotFoundException>(() => inv.Purchase(99), "purchasing a missing item throws ItemNotFoundException");

        Console.WriteLine("InventoryService: add");
        inv = NewService();
        var added = inv.Add("  Desk Lamp  ", "furniture", 5);
        Check.Equal(4, added.Id, "new item gets the next id");
        Check.Equal("Desk Lamp", added.Name, "name is trimmed");
        Check.Equal(4, inv.GetAll().Count, "added item is stored");
        Check.Throws<ArgumentException>(() => inv.Add("   ", "paper", 1), "blank name throws ArgumentException");
        Check.Throws<ArgumentException>(() => inv.Add("Pen", "paper", -1), "negative stock throws ArgumentException");
        Check.Throws<UnknownCategoryException>(() => inv.Add("Pen", "papyrus", 1),
            "unknown category on add throws UnknownCategoryException");

        return Check.Summary();
    }

